function TrailHeaderCollaboration({
  org,
  repo,
  number,
  username,
  threads,
  defaultThreadId,
  focusedThreadId,
  threadsOpen,
  onThreadsOpenChange,
  bodyPresenceUsers,
}: {
  org: string
  repo: string
  number: number
  username?: string | null
  threads: TrailThreadSummary[]
  defaultThreadId: string | null
  focusedThreadId: string | null
  threadsOpen: boolean
  onThreadsOpenChange: (open: boolean) => void
  bodyPresenceUsers: EditorPresenceUser[]
}) {
  const [hasUnreadThreadMessages, setHasUnreadThreadMessages] = useState(false)
  const incomingThreadTimestamps = useMemo(
    () => getIncomingThreadTimestamps(threads, username),
    [threads, username],
  )
  const latestIncomingThreadTimestamp = useMemo(
    () => getLatestThreadTimestamp(incomingThreadTimestamps),
    [incomingThreadTimestamps],
  )
  const threadReadStorageKey = useMemo(
    () => getThreadReadStorageKey({ username, org, repo, number }),
    [username, org, repo, number],
  )

  const markThreadRead = useCallback(() => {
    writeThreadTimestamp(threadReadStorageKey, latestIncomingThreadTimestamp ?? Date.now())
    setHasUnreadThreadMessages(false)
  }, [latestIncomingThreadTimestamp, threadReadStorageKey])

  const handleThreadsOpenChange = useCallback(
    (open: boolean) => {
      onThreadsOpenChange(open)
      if (open) markThreadRead()
    },
    [markThreadRead, onThreadsOpenChange],
  )

  useEffect(() => {
    const lastReadTimestamp = readThreadTimestamp(threadReadStorageKey)

    if (lastReadTimestamp === null) {
      writeThreadTimestamp(threadReadStorageKey, latestIncomingThreadTimestamp ?? Date.now())
      setHasUnreadThreadMessages(false)
      return
    }

    setHasUnreadThreadMessages(
      latestIncomingThreadTimestamp !== null && latestIncomingThreadTimestamp > lastReadTimestamp,
    )
  }, [latestIncomingThreadTimestamp, threadReadStorageKey])

  useEffect(() => {
    if (threadsOpen) markThreadRead()
  }, [threadsOpen, markThreadRead])

  useKeybindings(
    {
      t: (event) => {
        event.preventDefault()
        handleThreadsOpenChange(true)
      },
    },
    { enabled: !threadsOpen },
  )

  return (
    <div className="flex min-w-0 items-center justify-end gap-2">
      {bodyPresenceUsers.length > 0 ? (
        <div className="hidden min-w-0 sm:block">
          <EditorPresenceAvatars users={bodyPresenceUsers} />
        </div>
      ) : null}
      <Dialog open={threadsOpen} onOpenChange={handleThreadsOpenChange}>
        <DialogTrigger asChild>
          <Button size="small" variant="outline" condensed aria-label="Open threads">
            <span className="relative shrink-0">
              <MessageCircle size={16} className="text-muted" />
              {hasUnreadThreadMessages && (
                <span className="absolute right-0 bottom-0 size-1.5 rounded-full bg-orange-500" />
              )}
            </span>
            <span>Threads</span>
            <Kbd className="pointer-coarse:hidden">T</Kbd>
          </Button>
        </DialogTrigger>
        <TrailThreadsPanel
          org={org}
          repo={repo}
          number={number}
          username={username}
          initialThreadId={defaultThreadId}
          focusedThreadId={focusedThreadId}
        />
      </Dialog>
    </div>
  )
}

